package com.bank.nnmig.db;

import java.util.*;
import java.util.logging.Logger;

// A large table where branch_code is initially null for every row.
public class BigTable {
    private static final Logger log = Logger.getLogger(BigTable.class.getName());
    private final Map<Long, String> branchCode = new LinkedHashMap<>();   // id → branch_code (null allowed)
    private boolean notNullEnforced = false;

    public BigTable(long rows) { for (long i = 1; i <= rows; i++) branchCode.put(i, null); }

    public long countNulls() { return branchCode.values().stream().filter(Objects::isNull).count(); }

    // Backfill up to 'limit' null rows in ONE short transaction.
    public int backfillBatch(String value, int limit) {
        int done = 0;
        for (Map.Entry<Long,String> e : branchCode.entrySet()) {
            if (done >= limit) break;
            if (e.getValue() == null) { e.setValue(value); done++; }
        }
        final int d = done;
        log.fine(() -> "backfilled batch of " + d + " (remaining nulls=" + countNulls() + ")");
        return done;
    }

    // Attempt to enforce NOT NULL — fails if any null remains.
    public void setNotNull() {
        if (countNulls() > 0) throw new IllegalStateException("NOT NULL violation: " + countNulls() + " nulls remain");
        notNullEnforced = true;
        log.info("NOT NULL enforced on branch_code");
    }

    public boolean isNotNullEnforced() { return notNullEnforced; }
}
