package com.bank.nnmig.migrate;

import com.bank.nnmig.db.BigTable;
import java.util.logging.*;

public class SchemaMigrator {
    private static final Logger log = Logger.getLogger(SchemaMigrator.class.getName());

    // The WRONG way: enforce NOT NULL while nulls still exist.
    public void directEnforce(BigTable t) {
        try { t.setNotNull(); }
        catch (RuntimeException ex) { log.log(Level.SEVERE, "direct SET NOT NULL failed", ex); }
    }

    // The RIGHT way: batched backfill then enforce.
    public void safeMigrate(BigTable t, String value, int batchSize) {
        log.info(() -> "nulls before backfill: " + t.countNulls());
        int batch; int batches = 0;
        do {
            batch = t.backfillBatch(value, batchSize);   // each a short transaction
            batches++;
        } while (batch > 0);
        final int b = batches;
        log.info(() -> "backfill complete in " + b + " batches; nulls now " + t.countNulls());
        t.setNotNull();                                  // safe: zero nulls remain
    }
}
