package com.bank.nnmig;

import com.bank.nnmig.db.BigTable;
import com.bank.nnmig.migrate.SchemaMigrator;
import java.util.logging.*;

public class NotNullMigrationDemo {
    private static final Logger log = Logger.getLogger(NotNullMigrationDemo.class.getName());

    public static void main(String[] args) {
        setupLogger();
        SchemaMigrator migrator = new SchemaMigrator();

        log.info("=== WRONG: direct NOT NULL on a table full of nulls ===");
        BigTable t1 = new BigTable(12000);
        migrator.directEnforce(t1);   // fails

        log.info("=== RIGHT: add nullable → backfill in batches → enforce ===");
        BigTable t2 = new BigTable(12000);
        migrator.safeMigrate(t2, "DEL001", 5000);
        log.info(() -> "NOT NULL enforced? " + t2.isNotNullEnforced());
    }

    private static void setupLogger() {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }
}

